// ── Validate Emergency Request Payload ──────────────────────────────────
const inputItem = $input.first().json || {};
const headers = inputItem.headers || {};
const body = inputItem.body || (inputItem.headers ? {} : inputItem);

const ALLOWED_RESOURCES = ['BLOOD', 'OXYGEN', 'ICU_BED', 'VENTILATOR', 'MEDICINE', 'EQUIPMENT', 'AMBULANCE'];

const hospitalId = body.hospital_id || body.requesting_hospital_id;
if (!hospitalId || typeof hospitalId !== 'string') {
  return [{
    json: {
      isValid: false,
      statusCode: 400,
      error_code: 'INVALID_PAYLOAD',
      error: 'Missing or invalid hospital_id: must be a valid hospital UUID'
    }
  }];
}

const resourceType = (body.resource_type || '').toUpperCase();
if (!ALLOWED_RESOURCES.includes(resourceType)) {
  return [{
    json: {
      isValid: false,
      statusCode: 400,
      error_code: 'INVALID_RESOURCE_TYPE',
      error: `Invalid resource_type: "${body.resource_type}". Allowed values: ${ALLOWED_RESOURCES.join(', ')}`
    }
  }];
}

const requestId = body.request_id || `req-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;
const correlationId = body.correlation_id || headers['x-correlation-id'] || `CORR-${Date.now()}`;

return [{
  json: {
    ...body,
    hospital_id: hospitalId,
    resource_type: resourceType,
    request_id: requestId,
    correlation_id: correlationId,
    quantity: Number(body.quantity) || 1,
    radius_km: Number(body.radius_km) || 15.0,
    urgency: body.urgency || 'CRITICAL',
    isValid: true,
    statusCode: 200
  }
}];

